            "ห้ามวัด Ω ความต่อเนื่อง หรือไดโอดในวงจรที่มีไฟ ห้ามต่อแอมมิเตอร์ขนาน",
            "สวมแว่นตานิรภัยเมื่อวัดวงจรที่มีพลังงานสูง ทำงานในที่แห้ง",
